"use client";

import { useRef } from "react";
import { motion, useScroll, useTransform } from "framer-motion";

export function FinalSection() {
  const sectionRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start end", "end start"],
  });

  // Opacity-only reveals — GPU composited, no layout thrash
  const opacity1 = useTransform(scrollYProgress, [0.1, 0.25, 0.45], [0, 1, 0]);
  const opacity2 = useTransform(scrollYProgress, [0.4, 0.55, 0.75], [0, 1, 0]);
  const opacity3 = useTransform(scrollYProgress, [0.7, 0.85, 1],    [0, 1, 1]);

  return (
    <section
      ref={sectionRef}
      id="finale"
      className="relative min-h-[300vh] overflow-hidden"
    >
      {/* Sticky container — Earth renders in fixed SceneCanvas behind this */}
      <div className="sticky top-0 h-screen flex items-center justify-center overflow-hidden">
        {/* Dark overlay */}
        <div className="absolute inset-0 bg-[#050505]/25 pointer-events-none" />

        {/* Vignette */}
        <div
          className="absolute inset-0 pointer-events-none"
          style={{
            background:
              "radial-gradient(ellipse at center, transparent 30%, rgba(5,5,5,0.65) 100%)",
          }}
        />

        {/* Text beats */}
        <div className="relative z-10 text-center px-6">
          {/* Beat 1 */}
          <motion.div
            style={{ opacity: opacity1 }}
            className="absolute inset-0 flex items-center justify-center"
          >
            <h2 className="text-5xl md:text-8xl font-black text-white/80 leading-tight">
              We Don&apos;t Just
              <br />
              Build Software
            </h2>
          </motion.div>

          {/* Beat 2 */}
          <motion.div
            style={{ opacity: opacity2 }}
            className="absolute inset-0 flex items-center justify-center"
          >
            <h2
              className="text-5xl md:text-8xl font-black leading-tight text-gradient"
            >
              We Build
              <br />
              The Future
            </h2>
          </motion.div>

          {/* Beat 3 — final CTA */}
          <motion.div
            style={{ opacity: opacity3 }}
            className="absolute inset-0 flex flex-col items-center justify-center gap-8"
          >
            <h1
              className="text-7xl md:text-[12rem] font-black tracking-tighter leading-none text-gradient"
            >
              THINK
              <br />
              BEYOND
            </h1>

            <div className="flex flex-col items-center gap-4">
              <div className="w-px h-16 bg-gradient-to-b from-cyan-400/60 to-transparent" />
              <a
                href="#noorva"
                className="px-10 py-5 rounded-full text-white font-semibold text-lg transition-opacity duration-300 hover:opacity-90"
                style={{
                  background: "linear-gradient(135deg, #0066FF, #00E5FF)",
                }}
              >
                Begin The Journey
              </a>
              <p className="text-white/30 text-sm tracking-widest uppercase">
                Mahadeva Digital Solutions
              </p>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}
